\label{asm:bounded_norm}
We assume that $\|\phi(s, a)\|_2 \le 1$ for all $(s, a)\in{\mathcal{S}} \times \mathcal{A}$.
\vspace{-2mm}

\label{asm:linear_realizability}
There exists $b>0$ such that for every policy $\pi$, there exists a weight vector $w_\pi\in\mathbb{R}^d$, $\|w_\pi\|_2\le b$, that ensures $Q_\pi(s, a) = w_\pi^\top \phi(s, a) $ for all $(s, a)\in{\mathcal{S}} \times \mathcal{A}$.
\vspace{-2mm}

\label{lem:q_est_rand}
Let $\pi$ be a policy that we run rollout with in an iteration of the virtual algorithm.
Then, for any element $z\in\mathcal{C}$ and any $\theta>0$, we have with probability at least $1-2\exp(-2\theta^2(1-\gamma)^2m)$,
\begin{align}\label{eq:est_err_true_q}
|z_q - Q_\pi(z_s, z_a)| \le \frac{\gamma^{n+1}}{1-\gamma} + \theta.
\end{align}

\label{lem:est_error_rand}
Suppose that Assumption~\ref{asm:linear_realizability_prox} holds. Then, with probability at least 
\[
1-2C_{\max}\exp(-2\theta^2(1-\gamma)^2m),
\]
for any $(s, a)$ pair such that $\phi(s, a) \in \mathcal{H}$, we have
\begin{align}\label{eq:q_gap_virtual_rand}
|\widetilde{Q}_{k-1}(s, a) - Q_{\widetilde\pi_{k-1}}(s, a)| \le b\sqrt{\lambda \tau} +  \big(\epsilon + \frac{\gamma^{n+1}}{1-\gamma} + \theta\big) \sqrt{\tau C_{\max}}+\epsilon:=\eta.
\end{align}
